import React,{useState} from 'react';
export default function CustomerContext({data,state='ready',emit}){const [result,setResult]=useState('');const [busy,setBusy]=useState(false);if(state!=='ready')return <section className="state" data-state={state} role={state==='error'?'alert':'status'}><h2>{state==='loading'?'Loading context…':state==='empty'?'Nothing to show yet':'This view needs attention'}</h2><p>{state==='error'?'Refresh the authorized data source and try again.':'The workspace remains available.'}</p></section>;
const c=data.customer;async function act(){setBusy(true);try{await emit('intervention.create',{customerId:c.id,kind:'call',reason:'Check-in from customer context'});setResult('Action processed. Refresh the current context for the latest record.');}catch(e){setResult('Action did not complete. Check the host before retrying.');}finally{setBusy(false);}}return <div className="shell"><span className="eyebrow">Current customer / Authorized data</span><h1>{c.name}</h1><p>Evidence, context and the next safe step.</p><div className="grid"><section className="panel"><span className="eyebrow">Risk signal</span><div className="big">{c.riskScore}<span className="muted"> / 100</span></div><progress value={c.riskScore} max="100" aria-label="Customer risk score"/><p>{c.status}</p></section><section className="panel"><h2>Make the next step explicit.</h2><p>The host checks the customer, permissions and exact action before anything changes.</p><button id="intervene" className="btn" disabled={busy} onClick={act}>{busy?'Waiting for the host…':'Propose a check-in'}</button></section></div><p id="result" role="status" className="spacer">{result||'No action has been taken.'}</p></div>;}
